import csv, re
from collections import Counter
path='/app/dataset/data.csv'
cr=[]; par=[]; minus=[]; c1=[]; c2=[]; lowers=[]
chars=Counter()
notes_examples=[]
with open(path, newline='') as f:
    r=csv.DictReader(f)
    for i,row in enumerate(r):
        s=row['amount_str']
        chars.update(s)
        t=s.strip()
        if 'CR' in t: cr.append(t)
        if t.startswith('(') and t.endswith(')'): par.append(t)
        if '-' in t: minus.append(t)
        if 'C1' in t: c1.append(t)
        if 'C2' in t: c2.append(t)
        if re.search(r'[a-z]', t): lowers.append(t)
        if 'waive' in row['notes'].lower():
            notes_examples.append(row['notes'])
print('count CR', len(cr), 'sample', cr[:10])
print('count par', len(par), 'sample', par[:10])
print('count minus', len(minus), 'sample', minus[:10])
print('count C1', len(c1), 'sample', c1[:10])
print('count C2', len(c2), 'sample', c2[:10])
print('count lowercase letters in amount_str', len(lowers), 'sample', lowers[:10])
print('waive samples', notes_examples[:20])
print('chars', ''.join(sorted(chars)))
