import csv, math, re
from datetime import datetime, timezone
from statistics import median
from collections import defaultdict

path='/app/dataset/data.csv'

amount_re_letters = re.compile(r'[A-Za-z\s]')
amount_re_keep = re.compile(r'[^0-9,\.]')
item_re = re.compile(r'items=(\d+)')
adj_re = re.compile(r'adj=([+-]?\d+(?:\.\d+)?)%')
fee_re = re.compile(r'fee=([+-]?\d+(?:\.\d+)?)')
waive_re = re.compile(r'waive=true', re.I)

def parse_amount(s):
    if s is None:
        return math.nan
    s = s.strip()
    if not s:
        return math.nan
    neg = ('CR' in s) or ('-' in s) or (s.startswith('(') and s.endswith(')'))
    s = s.replace('C1', '').replace('C2', '')
    s = amount_re_letters.sub('', s)
    s = amount_re_keep.sub('', s)
    if not s:
        return math.nan
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            dec=','; thou='.'
        else:
            dec='.'; thou=','
        s = s.replace(thou, '')
        last = s.rfind(dec)
        s = s[:last].replace(dec, '') + '.' + s[last+1:]
    elif ',' in s or '.' in s:
        sep = ',' if ',' in s else '.'
        last = s.rfind(sep)
        digits_after = len(s)-last-1
        if digits_after == 2:
            s = s[:last].replace(sep, '') + '.' + s[last+1:]
        else:
            s = s.replace(sep, '')
    try:
        val = float(s)
    except ValueError:
        return math.nan
    return -val if neg else val

def parse_event_time(s):
    s=s.strip()
    if not s:
        return None
    return datetime.fromisoformat(s.replace('Z', '+00:00'))

def parse_notes(notes):
    m=item_re.search(notes)
    items=int(m.group(1)) if m else None
    m=adj_re.search(notes)
    adj=float(m.group(1))/100 if m else 0.0
    m=fee_re.search(notes)
    fee=float(m.group(1)) if m else 0.0
    waive=bool(waive_re.search(notes))
    return items, adj, fee, waive

rows=[]
with open(path, newline='') as f:
    r=csv.DictReader(f)
    for idx,row in enumerate(r):
        base=parse_amount(row['amount_str'])
        items, adj, fee, waive = parse_notes(row['notes'])
        if math.isnan(base):
            net=math.nan
        else:
            net=base*(1+adj)+fee
            if waive:
                net=0.0
        rows.append({
            'file_order': idx,
            'record_id': row['record_id'],
            'event_time': parse_event_time(row['event_time']),
            'region': row['region'],
            'channel': row['channel'],
            'items': items,
            'net': net,
        })

best={}
for row in rows:
    rid=row['record_id']
    cur=best.get(rid)
    if cur is None:
        best[rid]=row
        continue
    a=row['event_time']
    b=cur['event_time']
    if a is None and b is not None:
        better=False
    elif a is not None and b is None:
        better=True
    elif a != b:
        better=a>b
    else:
        a_real = not math.isnan(row['net'])
        b_real = not math.isnan(cur['net'])
        if a_real != b_real:
            better=a_real and not b_real
        else:
            better=row['file_order'] < cur['file_order']
    if better:
        best[rid]=row

def finite(x):
    return not math.isnan(x) and math.isfinite(x)

start=datetime(2025,10,1,0,0,0,tzinfo=timezone.utc)
end=datetime(2025,12,31,23,59,59,tzinfo=timezone.utc)
filtered=[]
for row in best.values():
    et=row['event_time']
    if et is None:
        continue
    if not (start <= et <= end):
        continue
    if row['channel'].strip().lower() == 'phone':
        continue
    if not finite(row['net']):
        continue
    row=row.copy()
    row['month']=et.strftime('%Y-%m')
    filtered.append(row)

groups=defaultdict(list)
for row in filtered:
    groups[(row['region'], row['month'])].append(row['net'])

stats={}
for k, vals in groups.items():
    med=median(vals)
    mad=median([abs(v-med) for v in vals])
    stats[k]=(med,mad)

for row in filtered:
    med,mad=stats[(row['region'], row['month'])]
    rz = 0.0 if mad == 0 else 0.6745*(row['net']-med)/mad
    row['robust_z']=rz
    row['abs_robust_z']=abs(rz)
    items_eff = row['items'] if row['items'] is not None else 1
    if items_eff < 1:
        items_eff = 1
    row['items_eff']=items_eff
    row['anomaly_score']=abs(rz)*math.log1p(items_eff)

filtered.sort(key=lambda r: (r['record_id']))
filtered.sort(key=lambda r: r['event_time'], reverse=True)
filtered.sort(key=lambda r: r['abs_robust_z'], reverse=True)
filtered.sort(key=lambda r: r['anomaly_score'], reverse=True)

print([r['record_id'] for r in filtered[:10]])
for r in filtered[:12]:
    print(r['record_id'], r['anomaly_score'], r['abs_robust_z'], r['event_time'].isoformat())
